// Sourcemap attribution of the MINIFIED first-load chunks, for the #2875 audit.
// Needs a build with sourcemaps plus out/graph.json:
//   npx vite build --sourcemap --config .scratch/bundle-audit/vite.measure.config.mjs
//   node .scratch/bundle-audit/attribute.mjs [--group <substring> ...]
// Each generated byte goes to the source of the mapping that starts its segment
// (the same rule source-map-explorer uses). "gzip" for a module is a gzip of its
// own minified slices joined: an upper bound on what removing it saves, because a
// module compresses better inside its chunk. --group prints the joined gzip of
// every first-load module whose path contains any substring (a slice estimate).
import { readFileSync, writeFileSync } from 'node:fs'
import { gzipSync } from 'node:zlib'
import { SourceMapConsumer } from 'source-map-js'

const ROOT = new URL('../../', import.meta.url).pathname
const g = JSON.parse(readFileSync(new URL('./out/graph.json', import.meta.url)))
const byFile = Object.fromEntries(g.chunks.map((c) => [c.file, c]))
const entry = g.chunks.find((c) => c.isEntry)
const closure = new Set()
const walk = (f) => { if (closure.has(f)) return; closure.add(f); for (const i of byFile[f].imports) walk(i) }
walk(entry.file)

const norm = (s) => s.replace(/^(\.\.\/)+/, '').replace(/^\.?\/?/, '')
const pieces = {} // source -> { chunk -> string[] }
let total = 0
const chunkTotals = {}
for (const f of closure) {
  const code = readFileSync(ROOT + 'dist/' + f, 'utf8')
  const map = JSON.parse(readFileSync(ROOT + 'dist/' + f + '.map', 'utf8'))
  const lines = code.split('\n')
  const lineStart = []
  let off = 0
  for (const l of lines) { lineStart.push(off); off += l.length + 1 }
  const ms = []
  new SourceMapConsumer(map).eachMapping((m) => ms.push([lineStart[m.generatedLine - 1] + m.generatedColumn, m.source ? norm(m.source) : `[no map: ${f.replace(/^assets\//, '').replace(/-[\w-]{8}\.js$/, '')} json/exports]`]))
  ms.sort((a, b) => a[0] - b[0])
  const cut = code.lastIndexOf('\n//# sourceMappingURL')
  const end = cut > 0 ? cut : code.length
  chunkTotals[f] = { raw: Buffer.byteLength(code.slice(0, end)), gzip: gzipSync(code.slice(0, end)).length }
  total += chunkTotals[f].raw
  const add = (src, s) => { ((pieces[src] ??= {})[f] ??= []).push(s) }
  if (ms.length && ms[0][0] > 0) add('[unmapped head]', code.slice(0, ms[0][0]))
  for (let i = 0; i < ms.length; i++) {
    const from = ms[i][0], to = i + 1 < ms.length ? ms[i + 1][0] : end
    if (to > from) add(ms[i][1], code.slice(from, Math.min(to, end)))
  }
}

const rows = Object.entries(pieces).map(([src, per]) => {
  const all = Object.values(per).flat().join('')
  return { src, chunks: Object.keys(per), raw: Buffer.byteLength(all), gzip: gzipSync(all).length, inEntry: !!per[entry.file] }
}).sort((a, b) => b.raw - a.raw)
writeFileSync(new URL('./out/attribution.json', import.meta.url), JSON.stringify({ chunkTotals, rows }, null, 1))

const kb = (n) => (n / 1000).toFixed(1)
const gi = process.argv.indexOf('--group')
if (gi > 0) {
  const subs = process.argv.slice(gi + 1)
  const hit = rows.filter((r) => subs.some((s) => r.src.includes(s)))
  const joined = hit.map((r) => Object.values(pieces[r.src]).flat().join('')).join('')
  console.log(`${hit.length} modules, ${kb(Buffer.byteLength(joined))} kB raw, ${kb(gzipSync(joined).length)} kB gzip (joined)`)
  for (const r of hit.slice(0, 15)) console.log(`  ${kb(r.raw).padStart(6)} ${kb(r.gzip).padStart(5)}  ${r.src}`)
  process.exit(0)
}
console.log(`first-load closure: ${closure.size} chunks, ${kb(total)} kB raw`)
const e = chunkTotals[entry.file]
console.log(`entry ${entry.file}: ${kb(e.raw)} kB raw, ${kb(e.gzip)} kB gzip`)
console.log('\nTOP 20 MODULES IN THE ENTRY CHUNK (minified bytes from the sourcemap)')
for (const r of rows.filter((r) => r.inEntry).slice(0, 22)) console.log(`${kb(r.raw).padStart(7)} ${kb(r.gzip).padStart(6)}  ${r.src}`)
console.log('\nJSON MODULES IN FIRST-LOAD CHUNKS (pre-minify renderedLength; no sourcemap, so they land in [no map: <chunk>])')
for (const f of closure) for (const m of byFile[f].modules) if (m.id.endsWith('.json') && m.rendered > 3000) console.log(`${kb(m.rendered).padStart(7)}  ${m.id}  [${f}]`)
console.log('\nTOP 25 MODULES IN THE WHOLE FIRST LOAD')
for (const r of rows.slice(0, 25)) console.log(`${kb(r.raw).padStart(7)} ${kb(r.gzip).padStart(6)}  ${r.src}  [${r.chunks.map((c) => c.replace(/^assets\//, '').replace(/-[\w-]{8}\.js$/, '')).join(',')}]`)
